async function pageFunction(context) {
  const { page, Apify } = context;
  const sleep = (ms) => new Promise(r => setTimeout(r, ms));

  // Smart clearance detection function
  function detectClearanceLevel(text) {
    const lowerText = text.toLowerCase();

    if (lowerText.includes('ts/sci') || lowerText.includes('ts-sci') || lowerText.includes('tssci')) {
      if (lowerText.includes('poly')) return 'TS/SCI Poly';
      return 'TS/SCI';
    }
    if (lowerText.includes('top secret') || lowerText.match(/\bts\b/)) {
      if (lowerText.includes('poly')) return 'Top Secret Poly';
      return 'Top Secret';
    }
    if (lowerText.includes('secret') && !lowerText.includes('top secret')) {
      return 'Secret';
    }
    if (lowerText.includes('public trust')) {
      return 'Public Trust';
    }
    if (lowerText.includes('naci')) {
      return 'NACI';
    }
    return null;
  }

  async function waitForJobs(timeout = 30000) {
    try {
      await page.waitForFunction(
        () => Array.from(document.querySelectorAll('a[href*="/job-"]')).some(a => /\/job-\d+\//.test(a.getAttribute('href'))),
        { timeout }
      );
      return true;
    } catch(e) {
      console.log('No jobs found on this page');
      return false;
    }
  }

  // Function to extract full job details from a job page
  async function extractJobDetails(jobUrl) {
    try {
      await page.goto(jobUrl, { waitUntil: 'networkidle2', timeout: 45000 });
      await sleep(1500);

      const jobData = await page.evaluate(() => {
        const result = {};

        // Job Title from h1
        const h1 = document.querySelector('h1');
        result.jobTitle = h1 ? h1.innerText.trim() : null;

        // Job Number from URL path
        const jobSegment = window.location.pathname.split('/').filter(p => p.startsWith('job-'))[0];
        result.jobNumber = jobSegment ? jobSegment.replace('job-', '') : null;

        // Date Posted from itemprop
        const datePostedEl = document.querySelector('[itemprop="datePosted"]');
        result.datePosted = datePostedEl ? datePostedEl.innerText.trim() : null;

        // Location from itemprop elements
        const cityEl = document.querySelector('[itemprop="addressLocality"]');
        const stateEl = document.querySelector('[itemprop="addressRegion"]');
        const city = cityEl ? cityEl.innerText.trim().replace(',', '').trim() : '';
        const state = stateEl ? stateEl.innerText.trim() : '';
        result.location = [city, state].filter(Boolean).join(', ');

        // Employment Type from itemprop
        const empTypeEl = document.querySelector('[itemprop="employmentType"]');
        result.employmentType = empTypeEl ? empTypeEl.innerText.trim() : null;

        // Pay Rate from specific div
        const payRateDiv = document.querySelector('#ContentPlaceHolder1_divPayRate');
        if (payRateDiv) {
          const payText = payRateDiv.innerText.replace('Pay Rate', '').trim();
          result.payRate = payText || null;
        }

        // Category and Req #
        const boldElements = document.querySelectorAll('.bold');
        boldElements.forEach(el => {
          const text = el.innerText.trim();
          if (text === 'Category') {
            const nextDiv = el.nextElementSibling;
            if (nextDiv) result.category = nextDiv.innerText.trim();
          }
          if (text === 'Req #') {
            const nextDiv = el.nextElementSibling;
            if (nextDiv) result.reqNumber = nextDiv.innerText.trim();
          }
        });

        // Extract full description from body text
        const allText = document.body.innerText;

        const startJobDesc = allText.indexOf('JOB DESCRIPTION');
        const startSkills = allText.indexOf('REQUIRED SKILLS & EXPERIENCE');
        const endContent = allText.indexOf('Benefit packages for this role');
        const eeoStart = allText.indexOf('We are a company committed');

        let jobDesc = '';
        let skills = '';

        // Extract Job Description section
        if (startJobDesc > -1) {
          const endOfDesc = startSkills > -1 ? startSkills : (endContent > -1 ? endContent : (eeoStart > -1 ? eeoStart : startJobDesc + 3000));
          jobDesc = allText.substring(startJobDesc + 15, endOfDesc).trim();
        }

        // Extract Required Skills section
        if (startSkills > -1) {
          const endOfSkills = endContent > -1 ? endContent : (eeoStart > -1 ? eeoStart : startSkills + 3000);
          skills = allText.substring(startSkills + 28, endOfSkills).trim();
        }

        // Combine into full description
        let fullDesc = '';
        if (jobDesc) {
          fullDesc = jobDesc;
        }
        if (skills) {
          fullDesc += '\n\nREQUIRED SKILLS & EXPERIENCE:\n' + skills;
        }
        result.description = fullDesc.trim();

        // Extract duration patterns
        const durationPatterns = [
          /Duration[:\s]*([^\n]+)/i,
          /Contract Length[:\s]*([^\n]+)/i,
          /Project Duration[:\s]*([^\n]+)/i
        ];

        result.duration = null;
        for (const pattern of durationPatterns) {
          const match = allText.match(pattern);
          if (match) {
            result.duration = match[1].trim();
            break;
          }
        }

        return result;
      });

      return jobData;

    } catch (error) {
      console.log('Error extracting job details from ' + jobUrl + ': ' + error.message);
      return null;
    }
  }

  // Main scraping function
  console.log('=== Starting Insight Global Clearance Jobs Scrape ===');
  console.log('*** FULL PRODUCTION MODE ***');
  console.log('Keyword: Clearance');
  console.log('Searching ALL locations nationally\n');

  const baseUrl = 'https://insightglobal.com/jobs/find_a_job/?srch=Clearance';

  console.log('Starting URL: ' + baseUrl);
  await page.goto(baseUrl, { waitUntil: 'networkidle2', timeout: 45000 });

  // Check if jobs exist
  const hasJobs = await waitForJobs();
  if (!hasJobs) {
    console.log('No jobs found for keyword Clearance');
    return [];
  }

  // Paginate through all result pages
  let pageNum = 1;
  const maxPages = 100;
  const seenUrls = new Set();
  let totalJobsExtracted = 0;

  while (pageNum <= maxPages) {
    console.log('\n=== Processing listing page ' + pageNum + ' ===');

    // Extract job links from current listing page
    const pageJobLinks = await page.$$eval('a[href*="/job-"]',
      els => els.map(e => ({
        title: e.innerText.trim(),
        url: e.href
      })).filter(x => /\/job-\d+\//.test(x.url))
    );

    // Deduplicate job links on this page
    const uniqueJobLinks = [];
    for (const job of pageJobLinks) {
      if (!seenUrls.has(job.url)) {
        seenUrls.add(job.url);
        uniqueJobLinks.push(job);
      }
    }

    console.log('Found ' + uniqueJobLinks.length + ' unique jobs on page ' + pageNum);

    // Store the next page URL before we navigate away
    const nextPageLink = await page.evaluate(() => {
      const nextLink = document.querySelector('a.page-link[title="Page Forward"]');
      return nextLink ? nextLink.href : null;
    });

    // Now extract full details for each job on this page
    for (let i = 0; i < uniqueJobLinks.length; i++) {
      const jobLink = uniqueJobLinks[i];
      console.log('Extracting job ' + (i + 1) + '/' + uniqueJobLinks.length + ' on page ' + pageNum + ': ' + jobLink.title);

      const jobDetails = await extractJobDetails(jobLink.url);

      if (jobDetails) {
        // Detect clearance level from title and description
        const clearanceText = (jobDetails.jobTitle || '') + ' ' + (jobDetails.description || '');
        const detectedClearance = detectClearanceLevel(clearanceText);

        const fullJob = {
          url: jobLink.url,
          jobNumber: jobDetails.jobNumber,
          jobTitle: jobDetails.jobTitle,
          location: jobDetails.location,
          employmentType: jobDetails.employmentType,
          datePosted: jobDetails.datePosted,
          securityClearance: detectedClearance,
          payRate: jobDetails.payRate,
          duration: jobDetails.duration,
          category: jobDetails.category,
          reqNumber: jobDetails.reqNumber,
          description: jobDetails.description,
          scrapedAt: new Date().toISOString()
        };

        // PUSH DATA IMMEDIATELY - this outputs to dataset right away
        await Apify.pushData(fullJob);
        totalJobsExtracted++;

        console.log('  -> OUTPUT #' + totalJobsExtracted + ': ' + fullJob.jobTitle + ' | ' + fullJob.location + ' | ' + (fullJob.securityClearance || 'Clearance TBD'));
      }

      // Small delay between job extractions
      await sleep(Math.random() * 1000 + 500);
    }

    console.log('Completed page ' + pageNum + ': Total jobs extracted: ' + totalJobsExtracted);

    // Check if there's a next page
    if (!nextPageLink) {
      console.log('\nNo more pages - reached end of results at page ' + pageNum);
      break;
    }

    // Navigate to next listing page
    console.log('\nNavigating to page ' + (pageNum + 1) + '...');
    await page.goto(nextPageLink, { waitUntil: 'networkidle2', timeout: 45000 });
    await sleep(Math.random() * 1500 + 1000);

    const hasMoreJobs = await waitForJobs();
    if (!hasMoreJobs) {
      console.log('No jobs on page ' + (pageNum + 1) + ', ending search');
      break;
    }

    pageNum++;
  }

  // Final summary
  console.log('\n=== SCRAPING COMPLETE ===');
  console.log('Total unique jobs extracted: ' + totalJobsExtracted);

  // Return empty array since we already pushed all data
  return [];
}
